assert len(files) == len(expected), f"file count {len(files)} != {len(expected)}"
cm = ru = di = 0
for cid in expected:
    path = os.path.join(OUT, cid + ".json")
    with open(path, encoding="utf-8") as f:
        rec = json.load(f)
    assert rec["case_id"] == cid, f"case_id mismatch {cid}"
    for k in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
        assert k in rec and rec[k] not in (None, ""), f"missing field {k} in {cid}"
    t = rec["trigger"]
    for k in ("changed_main", "reserve_used", "disputed", "reason"):
        assert k in t, f"trigger missing {k} in {cid}"
    assert isinstance(rec["confidence"], (int, float)) and 0 <= rec["confidence"] <= 1
    cm += bool(t["changed_main"]); ru += bool(t["reserve_used"]); di += bool(t["disputed"])
print(f"OK written={written} files_verified={len(files)}")
print(f"trigger counts: changed_main={cm} reserve_used={ru} disputed={di}")
